// Extrai {filename, code} da resposta da IA.
const out = $input.first().json;
let text = String(out.text ?? out.output ?? out.response ?? '');
text = text.replace(/<think>[\s\S]*?<\/think>/gi, '').trim();
let data = null;
const start = text.indexOf('{');
const end = text.lastIndexOf('}');
if (start >= 0 && end > start) {
  // Modelos às vezes quebram linha "de verdade" dentro das strings do JSON: escapa.
  let json = '', inString = false, escaped = false;
  for (const ch of text.slice(start, end + 1)) {
    if (inString && !escaped && (ch === '\n' || ch === '\r' || ch === '\t')) {
      json += ch === '\n' ? '\\n' : ch === '\r' ? '' : '\\t';
      continue;
    }
    if (ch === '"' && !escaped) inString = !inString;
    escaped = ch === '\\' && !escaped;
    json += ch;
  }
  try { data = JSON.parse(json); } catch (e) { data = null; }
}
// Sem JSON: aceita o código num bloco de markdown.
if (!data || !data.code) {
  const m = text.match(/```(?:ts|typescript)?\n([\s\S]*?)```/);
  if (m) data = { filename: '', code: m[1] };
}
if (!data || !String(data.code || '').includes('test(')) throw new Error('A IA não devolveu um teste Playwright: ' + text.slice(0, 200));
return [{ json: { filename: String(data.filename || ''), code: String(data.code).trim() + '\n' } }];
